import React, { useEffect, useState } from "react";
import api from "../api/api";

export default function AdminDashboard() {
  const [stats, setStats] = useState({ users: 0, stores: 0, ratings: 0 });

  const [stores, setStores] = useState([]);
  const [storeFilter, setStoreFilter] = useState({ q: "", sortBy: "name", order: "ASC" });

  const [users, setUsers] = useState([]);
  const [userFilter, setUserFilter] = useState({ q: "", role: "", sortBy: "name", order: "ASC" });

  const [newStore, setNewStore] = useState({ name: "", email: "", address: "" });
  const [storeMsg, setStoreMsg] = useState("");

  const [newUser, setNewUser] = useState({
    name: "",
    email: "",
    address: "",
    password: "",
    role: "user"
  });
  const [userMsg, setUserMsg] = useState("");

  useEffect(() => {
    loadStats();
    loadStores();
    loadUsers();
  }, []);

  // Reload when filters change
  useEffect(() => { loadStores(); }, [storeFilter]);
  useEffect(() => { loadUsers(); }, [userFilter]);

  const loadStats = async () => {
    try {
      const res = await api.get("/admin/stats");
      setStats(res.data.stats);
    } catch (err) {
      console.error("Failed to load stats", err);
    }
  };

  const loadStores = async () => {
    try {
      const params = { ...storeFilter };
      const res = await api.get("/stores", { params });
      setStores(res.data.stores);
    } catch (err) {
      console.error(err);
    }
  };

  const loadUsers = async () => {
    try {
      const params = { ...userFilter };
      if (!params.role) delete params.role; // don't send empty role
      const res = await api.get("/users", { params });
      setUsers(res.data.users);
    } catch (err) {
      console.error(err);
    }
  };

  // --- Add Store ---
  const handleStoreChange = (e) => {
    setNewStore({ ...newStore, [e.target.name]: e.target.value });
  };

  const handleAddStore = async (e) => {
    e.preventDefault();
    try {
      await api.post("/stores", newStore);
      setStoreMsg("Store added successfully!");
      setNewStore({ name: "", email: "", address: "" });
      loadStats(); loadStores();
    } catch (err) {
      console.error(err);
      setStoreMsg("Error adding store");
    }
  };

  // --- Add User ---
  const handleUserChange = (e) => {
    setNewUser({ ...newUser, [e.target.name]: e.target.value });
  };

  const handleAddUser = async (e) => {
    e.preventDefault();
    try {
      await api.post("/auth/signup", newUser);
      setUserMsg("User created successfully!");
      setNewUser({
        name: "",
        email: "",
        address: "",
        password: "",
        role: "user"
      });
      loadStats(); loadUsers();
    } catch (err) {
      console.error(err);
      setUserMsg("Error creating user: " + (err.response?.data?.message || err.message));
    }
  };

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
      <h2 className="text-3xl font-bold mb-6 text-gray-800">Admin Dashboard</h2>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-white p-6 rounded-lg shadow border-l-4 border-blue-500">
          <h3 className="text-gray-500 text-sm uppercase">Total Users</h3>
          <p className="text-3xl font-bold text-gray-800">{stats.users}</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow border-l-4 border-green-500">
          <h3 className="text-gray-500 text-sm uppercase">Total Stores</h3>
          <p className="text-3xl font-bold text-gray-800">{stats.stores}</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow border-l-4 border-yellow-500">
          <h3 className="text-gray-500 text-sm uppercase">Total Ratings</h3>
          <p className="text-3xl font-bold text-gray-800">{stats.ratings}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* --- ADD STORE --- */}
        <div className="bg-white p-6 rounded-lg shadow">
          <h3 className="text-xl font-semibold mb-4 border-b pb-2">Add New Store</h3>
          <form onSubmit={handleAddStore} className="space-y-3">
            <input name="name" placeholder="Store Name" className="w-full p-2 border rounded" value={newStore.name} onChange={handleStoreChange} required />
            <input name="email" placeholder="Store Email" className="w-full p-2 border rounded" value={newStore.email} onChange={handleStoreChange} required />
            <input name="address" placeholder="Store Address" className="w-full p-2 border rounded" value={newStore.address} onChange={handleStoreChange} required />
            <button type="submit" className="w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 transition">Add Store</button>
          </form>
          {storeMsg && <p className="mt-2 text-green-600 text-sm">{storeMsg}</p>}
        </div>

        {/* --- ADD USER --- */}
        <div className="bg-white p-6 rounded-lg shadow">
          <h3 className="text-xl font-semibold mb-4 border-b pb-2">Add New User</h3>
          <form onSubmit={handleAddUser} className="space-y-3">
            <input name="name" placeholder="Full Name (20+ chars)" className="w-full p-2 border rounded" value={newUser.name} onChange={handleUserChange} required />
            <input name="email" placeholder="Email" className="w-full p-2 border rounded" value={newUser.email} onChange={handleUserChange} required />
            <input name="address" placeholder="Address" className="w-full p-2 border rounded" value={newUser.address} onChange={handleUserChange} required />
            <input type="password" name="password" placeholder="Password" className="w-full p-2 border rounded" value={newUser.password} onChange={handleUserChange} required />
            <select name="role" className="w-full p-2 border rounded" value={newUser.role} onChange={handleUserChange}>
              <option value="user">User</option>
              <option value="owner">Owner</option>
              <option value="admin">Admin</option>
            </select>
            <button type="submit" className="w-full bg-green-600 text-white py-2 rounded hover:bg-green-700 transition">Add User</button>
          </form>
          {userMsg && <p className="mt-2 text-green-600 text-sm">{userMsg}</p>}
        </div>
      </div>

      {/* --- STORES LIST --- */}
      <div className="mt-10 bg-white p-6 rounded-lg shadow">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-xl font-semibold">Stores List</h3>
          <div className="flex gap-2">
            <input
              placeholder="Search Name/Address..."
              className="p-2 border rounded text-sm"
              value={storeFilter.q}
              onChange={(e) => setStoreFilter({ ...storeFilter, q: e.target.value })}
            />
            <select
              className="p-2 border rounded text-sm"
              value={storeFilter.sortBy}
              onChange={(e) => setStoreFilter({ ...storeFilter, sortBy: e.target.value })}
            >
              <option value="name">Sort by Name</option>
              <option value="email">Sort by Email</option>
              <option value="address">Sort by Address</option>
            </select>
            <select
              className="p-2 border rounded text-sm"
              value={storeFilter.order}
              onChange={(e) => setStoreFilter({ ...storeFilter, order: e.target.value })}
            >
              <option value="ASC">Ascending</option>
              <option value="DESC">Descending</option>
            </select>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-100 border-b">
                <th className="p-3">Name</th><th className="p-3">Email</th><th className="p-3">Address</th><th className="p-3">Rating</th>
              </tr>
            </thead>
            <tbody>
              {stores.map((s) => (
                <tr key={s.id} className="border-b hover:bg-gray-50">
                  <td className="p-3">{s.name}</td>
                  <td className="p-3">{s.email}</td>
                  <td className="p-3">{s.address}</td>
                  <td className="p-3 font-bold text-yellow-600">{s.averageRating} ★</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* --- USERS LIST --- */}
      <div className="mt-10 bg-white p-6 rounded-lg shadow">
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-xl font-semibold">Users List</h3>
          <div className="flex gap-2">
            <input
              placeholder="Search Name/Email..."
              className="p-2 border rounded text-sm"
              value={userFilter.q}
              onChange={(e) => setUserFilter({ ...userFilter, q: e.target.value })}
            />
            <select
              className="p-2 border rounded text-sm"
              value={userFilter.role}
              onChange={(e) => setUserFilter({ ...userFilter, role: e.target.value })}
            >
              <option value="">All Roles</option>
              <option value="user">User</option>
              <option value="owner">Owner</option>
              <option value="admin">Admin</option>
            </select>
            <select
              className="p-2 border rounded text-sm"
              value={userFilter.sortBy}
              onChange={(e) => setUserFilter({ ...userFilter, sortBy: e.target.value })}
            >
              <option value="name">Sort by Name</option>
              <option value="email">Sort by Email</option>
              <option value="address">Sort by Address</option>
              <option value="role">Sort by Role</option>
            </select>
            <select
              className="p-2 border rounded text-sm"
              value={userFilter.order}
              onChange={(e) => setUserFilter({ ...userFilter, order: e.target.value })}
            >
              <option value="ASC">Ascending</option>
              <option value="DESC">Descending</option>
            </select>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-100 border-b">
                <th className="p-3">Name</th><th className="p-3">Email</th><th className="p-3">Address</th><th className="p-3">Role</th>
              </tr>
            </thead>
            <tbody>
              {users.map((u) => (
                <tr key={u.id} className="border-b hover:bg-gray-50">
                  <td className="p-3">{u.name}</td>
                  <td className="p-3">{u.email}</td>
                  <td className="p-3">{u.address}</td>
                  <td className="p-3">
                    <span className={`px-2 py-1 rounded text-xs uppercase font-bold ${u.role === 'admin' ? 'bg-red-100 text-red-600' :
                        u.role === 'owner' ? 'bg-purple-100 text-purple-600' :
                          'bg-blue-100 text-blue-600'
                      }`}>
                      {u.role}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
